//! Region interior grids (`Region::region_grid`, C `astGetRegionMesh` with
//! `surface` unset) and a Prism's boundary mesh, checked against C. A Box
//! makes its grid with its base Frame's `frame_grid` (box.c `RegBaseGrid`);
//! any other Region keeps the points of a covering Box's grid that it
//! contains (region.c `RegBaseGrid`); a Prism builds its boundary from its
//! components' meshes and grids (prism.c `RegBaseMesh`).
//!
//! `region_grid_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/region_grid_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "region_grid_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::{BasicFrame, BasicFrameBuilder, CmpFrame, SkyFrame};
use ast_core::regions::{
    BoxRegionBuilder, CircleBuilder, IntervalBuilder, PolygonBuilder, PrismBuilder, Region,
};

const D2R: f64 = std::f64::consts::PI / 180.0;

fn plain(n: usize) -> BasicFrame {
    BasicFrameBuilder::new(n).build().unwrap()
}

fn rows(ps: &PointSet) -> Vec<Vec<f64>> {
    (0..ps.npoint()).map(|i| ps.point(i).to_vec()).collect()
}

fn check(name: &str, got: PointSet, want: &[&[f64]], failures: &mut Vec<String>) {
    let want: Vec<Vec<f64>> = want.iter().map(|r| r.to_vec()).collect();
    let got = rows(&got);
    if got != want {
        failures.push(format!(
            "{name}: got {} points {got:?}\nC gives {} points {want:?}",
            got.len(),
            want.len()
        ));
    }
}

#[test]
fn region_grids_follow_the_c_library() {
    let mut failures = Vec::new();
    let (lo, hi) = ([0.0, 0.0, 0.0], [1.0, 2.0, 3.0]);

    let mut b = BoxRegionBuilder::from_bounds(plain(2), &lo[..2], &hi[..2])
        .unwrap()
        .build()
        .unwrap();
    b.set_mesh_size(12);
    check(
        "BOX_PLAIN",
        b.region_grid().unwrap(),
        cases::BOX_PLAIN,
        &mut failures,
    );

    let cmp = CmpFrame::new(Box::new(plain(1)), Box::new(plain(1)));
    let mut b = BoxRegionBuilder::from_bounds(cmp, &lo[..2], &hi[..2])
        .unwrap()
        .build()
        .unwrap();
    b.set_mesh_size(12);
    check(
        "BOX_CMP",
        b.region_grid().unwrap(),
        cases::BOX_CMP,
        &mut failures,
    );

    let cmp = CmpFrame::new(Box::new(SkyFrame::unset_system()), Box::new(plain(1)));
    let mut b = BoxRegionBuilder::from_bounds(cmp, &[-0.2, -0.1, 0.0], &[0.2, 0.1, 3.0])
        .unwrap()
        .build()
        .unwrap();
    b.set_mesh_size(60);
    check(
        "BOX_SKY_CMP",
        b.region_grid().unwrap(),
        cases::BOX_SKY_CMP,
        &mut failures,
    );

    let mut circle = CircleBuilder::new(plain(2), vec![0.0, 0.0])
        .unwrap()
        .radius(1.0)
        .build()
        .unwrap();
    circle.set_mesh_size(40);
    check(
        "CIRCLE_PLAIN",
        circle.region_grid().unwrap(),
        cases::CIRCLE_PLAIN,
        &mut failures,
    );

    let mut c = CircleBuilder::new(SkyFrame::unset_system(), vec![0.0, 0.0])
        .unwrap()
        .radius(5.0 * D2R)
        .build()
        .unwrap();
    c.set_mesh_size(50);
    check(
        "CIRCLE_SKY",
        c.region_grid().unwrap(),
        cases::CIRCLE_SKY,
        &mut failures,
    );

    let vertices = [(25.0, -5.0), (25.0, 5.0), (35.0, 5.0), (35.0, -5.0)]
        .iter()
        .map(|&(lon, lat): &(f64, f64)| vec![lon * D2R, lat * D2R])
        .collect();
    let mut poly = PolygonBuilder::new(SkyFrame::unset_system(), vertices)
        .unwrap()
        .build()
        .unwrap();
    poly.set_mesh_size(40);
    check(
        "POLYGON_SKY",
        poly.region_grid().unwrap(),
        cases::POLYGON_SKY,
        &mut failures,
    );

    let interval = IntervalBuilder::new(plain(1), vec![0.0], vec![3.0])
        .unwrap()
        .build()
        .unwrap();
    let mut prism = PrismBuilder::new(circle, interval)
        .unwrap()
        .build()
        .unwrap();
    prism.set_mesh_size(60);
    check(
        "PRISM_MESH",
        prism.region_mesh().unwrap(),
        cases::PRISM_MESH,
        &mut failures,
    );
    check(
        "PRISM_GRID",
        prism.region_grid().unwrap(),
        cases::PRISM_GRID,
        &mut failures,
    );

    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}
